// Generate three distinct, small-range Arduino-like pin numbers to avoid conflicts
uint32_t base = *FUZZ_PARAM(unsigned int);
uint32_t pwmPin  = (base      ) % 64;          // plausible PWM-capable pin range proxy
uint32_t vsPin   = (base >> 6 ) % 64;          // plausible external interrupt-capable pin range proxy
uint32_t enPin   = (base >> 12) % 64;          // plausible GPIO pin for enable

// Ensure pins do not conflict with each other
if (vsPin == pwmPin) { vsPin = (vsPin + 1) % 64; }
if (enPin == pwmPin || enPin == vsPin) { enPin = (enPin + 1) % 64; if (enPin == pwmPin || enPin == vsPin) { FUZZ_BAIL(); } }

